def unique_in_order(items):
    """The items with duplicates removed, in the order they first appear."""
    items = list(items)
    try:
        seen = set()
        out = []
        for item in items:
            if item not in seen:
                seen.add(item)
                out.append(item)
        return out
    except TypeError:
        # Unhashable items (e.g. lists) can't go in a set, so fall back to a
        # linear scan, which only needs equality.
        seen = []
        out = []
        for item in items:
            if item not in seen:
                seen.append(item)
                out.append(item)
        return out
